examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true })
if (open) {
    MonarchDialog(
        onDismissRequest = { open = false },
        title = {{title}},
        description = {{description}},
        actions = {
            MonarchButton(text = "Cancel", onClick = { open = false }, variant = MonarchButtonVariant.Secondary)
            MonarchButton(
                text = {{submitLabel}},
                onClick = { open = false },
                variant = MonarchButtonVariant.Primary,
                enabled = !tooLong,
            )
        },
        content = {
            MonarchTextField(
                value = name,
                onValueChange = { name = it },
                label = {{label}},
                required = true,
                placeholder = {{placeholder}},
                errorText = if (tooLong) "Use " + {{maxLength}} + " characters or fewer." else null,
                keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
                keyboardActions = KeyboardActions(onDone = { if (name.isNotBlank() && !tooLong) open = false }),
            )
        },
    )
}

examples.setupTemplate:
