        actions = {
            MonarchButton(text = "Cancel", onClick = { open = false }, variant = MonarchButtonVariant.Secondary)
            MonarchButton(
                text = "Save view",
                onClick = { open = false },
                variant = MonarchButtonVariant.Primary,
                enabled = !tooLong,
            )
        },
        content = {
            MonarchTextField(
                value = name,
                onValueChange = { name = it },
                label = "View name",
                required = true,
                placeholder = "For example: Open this week",
                errorText = if (tooLong) "Use " + 60 + " characters or fewer." else null,
                keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
